{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "In a cynomolgus monkey, IV [O-methyl-11C]WAY-100634 showed avid brain radioactivity uptake comparable to WAY-100635, directly demonstrating meaningful CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "WAY-100635 (11C-131) given IV to cynomolgus monkeys reached 5.0% maximal brain uptake by PET, confirming robust BBB penetration in a higher species.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "[18F]MPPF in rats was a P-gp substrate with only 0.05% ID/g brain at 30 min, indicating that some close analogs can have insufficient CNS access.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most direct in-vivo evidence, including monkey PET and mouse biodistribution, supports meaningful CNS access. Negative low-uptake/efflux findings come from more distant analogs and do not override the positive systemic brain-uptake record.",
  "evidence_gaps": [
    "No direct query-specific measurement is available; prediction is based on structural analogs.",
    "Several positive records use radiotracer PET or biodistribution and may reflect total brain radioactivity rather than unbound brain exposure.",
    "Efflux substrate status was reported for some analogs without always providing baseline brain uptake, limiting interpretation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

